<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import ToolboxPage from '../ToolboxPage.vue'
const router = useRouter(); const voltaState = ref<VoltaNodeState>(); const voltaVersionInput = ref(''); const voltaSelectedVersion = ref(''); const voltaProjectPath = ref(''); const voltaBusy = ref(false); const voltaMessage = ref('读取本机 Volta 的 Node 工具链状态。'); const nodeReleases = ref<NodeRelease[]>([]); const nodeReleasesBusy = ref(false); const nodeReleasesMessage = ref('内置常用 Node LTS 版本；每个主版本仅显示最新可安装版。'); const managerInstallBusy = ref(false); const backToPortal = () => router.push({ name: 'portal' })
const voltaDownloadableReleases = computed(() => { const majors = new Set<string>(); return nodeReleases.value.filter((release) => { if (release.channel !== 'LTS') return false; const major = release.version.split('.')[0]; if (majors.has(major)) return false; majors.add(major); return true }) })
const refreshVoltaState = async () => { if (!window.voltaTools) return; voltaBusy.value = true; try { voltaState.value = await window.voltaTools.getNodeState(); if (!voltaSelectedVersion.value || !voltaState.value.versions.some((item) => item.version === voltaSelectedVersion.value)) voltaSelectedVersion.value = voltaState.value.defaultVersion ?? voltaState.value.versions[0]?.version ?? ''; voltaMessage.value = voltaState.value.installed ? '已读取 Volta 工具链。项目锁定的版本会优先于这里的默认版本。' : `未检测到可用的 Volta：${voltaState.value.error ?? '请确认 volta 已加入 PATH。'}` } catch (error) { voltaMessage.value = error instanceof Error ? error.message : String(error) } finally { voltaBusy.value = false } }
const refreshNodeReleases = async () => { if (!window.nodeReleaseTools) return; nodeReleasesBusy.value = true; try { nodeReleases.value = await window.nodeReleaseTools.list(); nodeReleasesMessage.value = `已加载 ${nodeReleases.value.length} 个内置 LTS 版本。` } catch (error) { nodeReleasesMessage.value = error instanceof Error ? error.message : String(error) } finally { nodeReleasesBusy.value = false } }
const installVoltaNode = async (version?: string) => { if (!window.voltaTools) return; const target = (version ?? voltaVersionInput.value).trim(); if (!target) { voltaMessage.value = '请输入要安装的 Node 版本。'; return } if (!window.confirm(`Volta 将下载 Node@${target} 并把它设为默认版本，是否继续？`)) return; voltaBusy.value = true; try { voltaState.value = await window.voltaTools.installNode(target); voltaSelectedVersion.value = voltaState.value.defaultVersion ?? target; voltaVersionInput.value = ''; voltaMessage.value = `Node@${voltaState.value.defaultVersion ?? target} 已安装，并已设为 Volta 默认版本。` } catch (error) { voltaMessage.value = error instanceof Error ? error.message : String(error) } finally { voltaBusy.value = false } }
const setVoltaDefault = async () => { if (!window.voltaTools || !voltaSelectedVersion.value) return; const version = voltaSelectedVersion.value; if (!window.confirm(`将 Volta 默认 Node 切换到 ${version}，是否继续？`)) return; voltaBusy.value = true; try { voltaState.value = await window.voltaTools.installNode(version); voltaSelectedVersion.value = voltaState.value.defaultVersion ?? version; voltaMessage.value = `Node@${voltaSelectedVersion.value} 已设为 Volta 默认版本。` } catch (error) { voltaMessage.value = error instanceof Error ? error.message : String(error) } finally { voltaBusy.value = false } }
const chooseVoltaProject = async () => { const selected = await window.developerTools.selectDirectory(); if (selected) voltaProjectPath.value = selected }
const pinVoltaNode = async () => { if (!window.voltaTools) return; const version = voltaVersionInput.value.trim() || voltaSelectedVersion.value || voltaState.value?.defaultVersion; if (!version) { voltaMessage.value = '请先输入要固定的 Node 版本。'; return } if (!voltaProjectPath.value) { voltaMessage.value = '请先选择项目目录。'; return } if (!window.confirm(`将修改该项目的 package.json，固定 Node@${version}。是否继续？`)) return; voltaBusy.value = true; try { const result = await window.voltaTools.pinNode(version, voltaProjectPath.value); voltaMessage.value = `已在 ${result.directory} 的 package.json 中固定 Node@${result.version}。` } catch (error) { voltaMessage.value = error instanceof Error ? error.message : String(error) } finally { voltaBusy.value = false } }
const installVersionManager = async () => { if (!window.nodeReleaseTools || !window.confirm('将通过 winget 安装 Volta。安装程序可能要求管理员授权，是否继续？')) return; managerInstallBusy.value = true; try { await window.nodeReleaseTools.installManager('volta'); await refreshVoltaState(); nodeReleasesMessage.value = 'Volta 安装命令已完成；如界面仍未识别，请重启 LocalForge。' } catch (error) { nodeReleasesMessage.value = error instanceof Error ? error.message : String(error) } finally { managerInstallBusy.value = false } }
void refreshVoltaState(); void refreshNodeReleases()
</script>
<template><ToolboxPage><header class="toolbox-heading"><div><p>数据工具 / VOLTA</p><h2>Node.js 版本管理</h2><span>这是 Volta 的可视化入口：界面直接调用本机 Volta，不替代它的版本管理机制。</span></div><button class="back-button" @click="backToPortal">‹ 返回工具列表</button></header><section class="volta-overview"><div class="volta-summary"><small>VOLTA</small><strong>{{ voltaState?.installed ? `v${voltaState.voltaVersion}` : '未检测' }}</strong><span>{{ voltaState?.installed ? '本机命令行工具链' : '请确认已安装并加入 PATH' }}</span></div><div class="volta-summary"><small>默认 NODE</small><strong>{{ voltaState?.defaultVersion ? `v${voltaState.defaultVersion}` : '—' }}</strong><span>全局默认；项目固定版本优先</span></div><div class="volta-summary"><small>当前 NODE</small><strong>{{ voltaState?.currentVersion ? `v${voltaState.currentVersion}` : '—' }}</strong><span>当前 LocalForge 工作目录的解析结果</span></div></section><section class="release-catalog"><header><div><p>VOLTA / DOWNLOADABLE NODE</p><h3>可下载 Node 版本</h3><span>内置当前处于 LTS 支持期的常用版本；每个主版本仅保留最新可安装版，安装时只调用 Volta。</span></div><button :disabled="nodeReleasesBusy" @click="refreshNodeReleases">{{ nodeReleasesBusy ? '读取中…' : '刷新列表' }}</button></header><p class="tool-message">{{ nodeReleasesMessage }}</p><div v-if="voltaDownloadableReleases.length" class="release-list"><div v-for="release in voltaDownloadableReleases" :key="release.version" class="release-row"><code>v{{ release.version }}</code><span>LTS</span><small>Node {{ release.version.split('.')[0] }} 主版本的最新 LTS</small><button class="primary" :disabled="voltaBusy || !voltaState?.installed" @click="installVoltaNode(release.version)">Volta 安装</button></div></div><p v-else-if="nodeReleases.length" class="empty-state">内置列表暂无 LTS 版本。</p></section><section v-if="!voltaState?.installed" class="manager-installs"><span>未检测到 Volta，可通过 winget 安装：</span><button :disabled="managerInstallBusy" @click="installVersionManager">{{ managerInstallBusy ? '正在安装 Volta…' : '安装 Volta' }}</button></section><section class="volta-actions"><label>已安装版本<select v-model="voltaSelectedVersion" :disabled="voltaBusy || !voltaState?.versions.length"><option v-for="item in voltaState?.versions ?? []" :key="item.version" :value="item.version">v{{ item.version }}{{ item.isDefault ? '（默认）' : '' }}</option></select></label><button :disabled="voltaBusy || !voltaSelectedVersion || voltaSelectedVersion === voltaState?.defaultVersion" @click="setVoltaDefault">{{ voltaSelectedVersion === voltaState?.defaultVersion ? '当前默认版本' : '设为默认' }}</button><label>安装新版本<input v-model.trim="voltaVersionInput" placeholder="例如 22、22.18.0、lts 或 latest" @keyup.enter="installVoltaNode()"></label><button class="primary" :disabled="voltaBusy" @click="installVoltaNode()">{{ voltaBusy ? '处理中…' : '安装并设为默认' }}</button><button :disabled="voltaBusy" @click="refreshVoltaState">刷新列表</button><p class="tool-message" :class="{ error: voltaState && !voltaState.installed }">{{ voltaMessage }}</p></section><section v-if="voltaState?.installed" class="results-card volta-versions"><header><div><strong>Volta Node 运行时</strong><small>直接读取 <code>volta list all</code>；该命令只列出本机 Volta 工具链。</small></div></header><div v-if="voltaState.versions.length" class="volta-version-list"><div v-for="item in voltaState.versions" :key="item.version" class="volta-version-row"><code>v{{ item.version }}</code><span v-if="item.isDefault">默认版本</span><button :disabled="voltaBusy || item.isDefault" @click="voltaSelectedVersion = item.version; setVoltaDefault()">{{ item.isDefault ? '正在使用' : '设为默认' }}</button></div></div><p v-else class="empty-state">Volta 未返回 Node 运行时。</p></section><section class="volta-pin"><div><strong>为项目固定 Node 版本</strong><span>会由 Volta 修改所选项目的 <code>package.json</code>，适合需要提交团队版本约束的项目。</span></div><input :value="voltaProjectPath" readonly placeholder="选择项目目录"><button @click="chooseVoltaProject">选择目录</button><button class="primary" :disabled="voltaBusy || !voltaProjectPath" @click="pinVoltaNode">固定到项目</button></section></ToolboxPage></template>
